pseek-ai/schemastery\": \"^3.18.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-api-remotes\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-base\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-connection\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-locale\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-runtime\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-credentials\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-settings\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-web\": \">=0.1.0-rc.6\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"@types/node\": \"^22.0.0\",\n    \"@types/react\": \"^18.2.0\",\n    \"puppeteer-core\": \"^25.8.0\",\n    \"react\": \"^18.2.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^6.0.0\"\n  },\n  \"scripts\": {\n    \"build\": \"tsdown --config ./tsdown.config.ts\",\n    \"test\": \"node tests/smoke.mjs\",\n    \"test:contract\": \"node tests/slot-contract-compat.mjs\",\n    \"typecheck\": \"tsc --noEmit\"\n  },\n  \"license\": \"MIT\"\n}\n"
